int zahl = 1;
int summe = 0;

while (zahl <= 5)
{
    summe += zahl;   // summe = summe + zahl
    zahl++;          // zahl = zahl + 1
}
Console.WriteLine($"1 + 2 + 3 + 4 + 5 = {summe}");
// Ausgabe: 1 + 2 + 3 + 4 + 5 = 15

