}

int note;

do
{
    Console.Write("Gib deine Note ein (1-5): ");
    note = int.Parse(Console.ReadLine());
} while (note < 1 || note > 5);

Console.WriteLine($"Danke, Note {note} gespeichert.");
// Eingaben: 7, dann 2
// Ausgabe:
// Gib deine Note ein (1-5): Gib deine Note ein (1-5): Danke, Note 2 gespeichert.

int x = 10;

while (x < 5)
{
    Console.WriteLine("while-Schleife");
}

do
{
    Console.WriteLine("do-while-Schleife");
} while (x < 5);
// Ausgabe: do-while-Schleife

